#include <bits/stdc++.h>
using namespace std;
int main(){const int X=30000000,K=100;vector<uint8_t> prime(X+1,1);prime[0]=prime[1]=0;for(int p=2;p*p<=X;p++)if(prime[p])for(int q=p*p;q<=X;q+=p)prime[q]=0;vector<int> w={5,10,20,40,60,100};vector<long double> a(w.size()),b(w.size()),c(w.size()),z(w.size());long long cnt=0;for(int N=1000030;N<=X;N+=60){cnt++;int m=N/2,h=0,idx=0;for(int j=1;j<=K;j++){if(j%5 && prime[m-6*j] && prime[m+6*j])h++;if(j==w[idx]){a[idx]+=h;b[idx]+=(long long)h*(h-1);c[idx]+=(long long)h*(h-1)*(h-2);z[idx]+=(h==0);idx++;if(idx==(int)w.size())break;}}}cout<<setprecision(10);for(int i=0;i<(int)w.size();i++){double mu=(double)(a[i]/cnt), f2=(double)(b[i]/cnt),f3=(double)(c[i]/cnt),k2=f2-mu*mu,k3=f3-3*f2*mu+2*mu*mu*mu;cout<<w[i]<<","<<mu<<","<<k2<<","<<k3<<","<<(double)(z[i]/cnt)<<","<<exp(-mu)<<","<<exp(-mu+k2/2)<<","<<exp(-mu+k2/2-k3/6)<<"\n";}}
